package com.cloudticket.inventory.security; public final class InventoryAuthorization {public boolean canAdjust(String permissions,String reason){return permissions!=null&&permissions.contains("inventory:adjust")&&reason!=null&&!reason.isBlank();} public boolean canRelease(String permissions,String reason){return permissions!=null&&permissions.contains("inventory:lock-release")&&reason!=null&&!reason.isBlank();}}
